-- Auto-set platform_organization_id from session var on INSERT
CREATE OR REPLACE FUNCTION claims.set_org_id_from_session()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.platform_organization_id IS NULL
       OR NEW.platform_organization_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
        NEW.platform_organization_id := nullif(current_setting('app.organization_id', true), '')::uuid;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_claim_set_org_id ON claims.claim;
CREATE TRIGGER trg_claim_set_org_id
    BEFORE INSERT ON claims.claim
    FOR EACH ROW
    EXECUTE FUNCTION claims.set_org_id_from_session();





